      </div>

      {/* Desktop Layout */}
      <div className="hidden md:block max-w-6xl mx-auto p-6">
        {/* Header */}
        <header className="flex items-center justify-between mb-8">
          <h1 className="text-2xl font-bold">Gewohnheitstracker</h1>
          <div className="flex gap-2">
            <Button
              variant="outline"
